F = np.load(WORK/'base_feats.npz'); y=F['y']
M = {L: F[f'mean_hidden_L{L}'][:,KEEP] for L in range(13)}
def zs(X,tr): mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; return (X-mu)/sd/np.sqrt(X.shape[1])
def add_cv(kb, lin, y, gammas, cs, lams, seeds=(0,1,2), k=5):
    n=len(y); res={}
    for s in seeds:
        for te in folds(n,k,s,y):
            tr=np.setdiff1d(np.arange(n),te)
            Z=zs(kb,tr); sq=(Z**2).sum(1); D2=np.maximum(sq[:,None]+sq[None]-2*Z@Z.T,0)
            ZL=np.concatenate([zs(X,tr) for X in lin],1)/np.sqrt(len(lin)) if lin else None
            KL=ZL@ZL.T if lin else 0
            T=np.eye(8)[y[tr]]-1/8
            for g in gammas:
                KR=np.exp(-g*D2)
                for c in cs:
                    K=KR+c*KL; w,V=np.linalg.eigh(K[np.ix_(tr,tr)]); R=V.T@T; Kte=K[np.ix_(te,tr)]
                    for l in lams:
                        key=(g,c,l); pred=(Kte@(V@(R/(w+l)[:,None]))).argmax(1)
                        res.setdefault(key,[0,0]); res[key][0]+=(pred==y[te]).sum(); res[key][1]+=len(te)
    return {k_:round(v[0]/v[1],4) for k_,v in res.items()}
for name,kb,lin in [('K8+L2L6',M[8],[M[2],M[6]]),('K8+L0',M[8],[M[0]]),('K9+L2L6',M[9],[M[2],M[6]]),('K9+L0',M[9],[M[0]]),
                    ('K1+L0',M[1],[M[0]]),('K6+L2',M[6],[M[2]]),('K7+L2L6',M[7],[M[2],M[6]])]:
    r=add_cv(kb,lin,y,(0.2,0.4),(0.3,1,3),(0.003,0.03))
    best=sorted(r.items(),key=lambda t:-t[1])[:3]
    print(name,best)
